import{_ as t,o as a,c as r,a2 as l}from"./chunks/framework.DoCD98hS.js";const u=JSON.parse('{"title":"认识 Melt JS","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1795182783000}'),i={name:"guide/introduction.md"};function o(n,e,d,s,c,h){return a(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="认识-melt-js" tabindex="-1">认识 Melt JS <a class="header-anchor" href="#认识-melt-js" aria-label="Permalink to &quot;认识 Melt JS&quot;">​</a></h1><p>Melt JS 基于 <a href="https://github.com/Tencent/hel" target="_blank" rel="noreferrer">Hel（hel-micro）</a> 加载远程模块，为 Vue 2、Vue 3 和 React 应用提供公共组件、应用模板和微前端页签。Hel 是腾讯开源的模块联邦 SDK，负责从托管地址加载模块；Melt JS 在它之上提供组件、加载工具和框架适配。你的应用继续管理页面、路由、状态和权限。</p><p>在微前端场景中，Hel 用来加载远程组件和页签适配层，qiankun 或 Wujie 负责挂载子应用。参见<a href="./micro-frontend-tabs.html">接入远程 Tab</a>。</p><p>启动时需要的组件可以先预加载，再从 npm 代理导入；偶尔使用的组件可以在页面或弹窗打开时加载。两种方式可以在一个项目中同时使用。只有组件实际拆成不同远程包时，懒加载才会减少首屏下载的包。</p><h2 id="按你的任务开始" tabindex="-1">按你的任务开始 <a class="header-anchor" href="#按你的任务开始" aria-label="Permalink to &quot;按你的任务开始&quot;">​</a></h2><ul><li><a href="./../modules/demos.html">在线体验组件</a>：选择框架，试用组件和属性面板。</li><li><a href="./getting-started.html">接入一个远程组件</a>：安装代理，预加载实现，在页面中使用磁吸按钮。</li><li><a href="./adapt-template.html">改造应用模板</a>：保留业务入口的逻辑，替换公共组件。</li><li><a href="./micro-frontend-tabs.html">接入远程 Tab</a>：分别配置页签、子应用挂载和保活。</li></ul>',6)])])}const p=t(i,[["render",o]]);export{u as __pageData,p as default};
